        (Label::Zero, Label::Zero) => true,
        (Label::Positive, Label::Positive) => true,
        (Label::Negative, Label::Negative) => true,
        (Label::Even, Label::Even) => true,
        (Label::Odd, Label::Odd) => true,
        (Label::Custom(a), Label::Custom(b)) => a == b,
        _ => false,
    }
}


