                    Option::Some(subst(x, *t2, *body)),
                _ => {
                    if !value(*t1) {
                        match step(*t1) {
                            Option::Some(t1p) =>
                                Option::Some(Tm::App { t1: Box::new(t1p), t2: t2 }),
                            Option::None => Option::None,
                        }
                    } else if !value(*t2) {
                        match step(*t2) {
                            Option::Some(t2p) =>
                                Option::Some(Tm::App { t1: t1, t2: Box::new(t2p) }),
