        index < N,
    ensures
        perm.ptr() == ptr,
        perm.is_uninit(index as int),
        forall|i: int| 0 <= i < N && i != index ==> perm.opt_value()[i] == old(perm).opt_value()[i],
        res == old(perm).opt_value()[index as int].value(),
    opens_invariants none
    no_unwind
{
