    }

    pub proof fn leak_contents(tracked &mut self, index: int)
        requires
            old(self).wf(),
        ensures
            self.wf(),
            self.addr() == old(self).addr(),
            self.is_uninit(index),
            forall|i: int|
                0 <= i < N && i != index ==> self.opt_value()[i] == old(self).opt_value()[i],
