    pub proof fn is_disjoint<S, const M: usize>(&self, other: &PointsTo<S, M>)
        ensures
            self.addr() + layout::size_of::<[V; N]>() <= other.addr() || other.addr()
                + layout::size_of::<[S; M]>() <= self.addr(),
    {
        self.points_to.is_disjoint(&other.points_to)
