    pub proof fn is_distinct<S, const M: usize>(&self, other: &PointsTo<S, M>)
        requires
            layout::size_of::<[V; N]>() != 0,
            layout::size_of::<[S; M]>() != 0,
        ensures
            self.addr() != other.addr(),
    {
        self.points_to.is_disjoint(&other.points_to);
    }
