                    (Tree::E, Tree::E) => Tree::E,
                    (Tree::E, r) => r,
                    (l, Tree::E) => l,
                    (l, r) => {
                        // Both children exist: replace with minimum of right subtree
                        let (min_k, min_v) = tree_min(r);
