/// Reading and writing to an array of values
#[inline(always)]
#[verifier::external_body]
pub exec fn ptr_mut_fill<V, const N: usize>(
    ptr: *mut [V; N],
    Tracked(perm): Tracked<&mut PointsToArray<V, N>>,
    value: V,
