        perm.is_init_all(),
        forall|i: int| 0 <= i < N ==> perm.opt_value()[i] == raw_ptr::MemContents::Init(value),
    opens_invariants none
    no_unwind
{
    for i in 0..N {
        unsafe {
            core::ptr::write((ptr as *mut V).add(i), value);
        }
    }
}

