pub trait Repr<R: Sized>: Sized {
    spec fn wf(r: R) -> bool;

    spec fn to_repr_spec(self) -> R;

    #[verifier::when_used_as_spec(to_repr_spec)]
    fn to_repr(self) -> (res: R)
