                it.valid(),
                it.index() == 0,
                it.list() == l,
        {
            Iterator { l, cur: l.head, index: Ghost(0) }
        }

        pub fn value(&self) -> (v: &V)
            requires
                self.valid(),
            ensures
                v == self.list()@[self.index() as int],
        {
            let cur = self.cur.unwrap();
            assert(self.l.well_formed_node(self.index()));
