        Expr::Succ { e } => 1 + expr_size(*e),
        Expr::Pred { e } => 1 + expr_size(*e),
        Expr::IsZero { e } => 1 + expr_size(*e),
        Expr::Let { def, body, .. } => 1 + expr_size(*def) + expr_size(*body),
    }
}


