fn vec_find(v: &Vec<usize>, needle: usize) -> (idx: usize)
    requires
        v@.contains(needle),
    ensures
        0 <= idx < v@.len() && v@[idx as int] == needle,
{
    let mut idx = 0;
    loop
        invariant
            v@.contains(needle),
            0 <= idx < v@.len(),
            forall|j| 0 <= j < idx ==> v@[j] != needle,
    {
        if v[idx] == needle {
            return idx;
        }
        assert(idx + 1 < v.len());
        idx = idx + 1;
    }
}

fn find_cycle(graph: &ConcreteDirectedGraph, dfs_state: &mut DfsState, v: usize)
    requires
