enum TopSortResult {
    TopSort(Vec<usize>),
    Cycle(Vec<usize>),
}

fn compute_top_sort(graph: &ConcreteDirectedGraph) -> (tsr: TopSortResult)
    requires
        graph.well_formed(),
    ensures
