state_machine!{
    MapSpec {
        fields {
            pub map: Map<Key, Value>,
        }

        init!{
            empty() {
                init map = Map::total(|k| default());
            }
        }

        transition!{
            insert_op(key: Key, value: Value) {
                update map = pre.map.insert(key, value);
            }
        }

        transition!{
            query_op(key: Key, value: Value) {
                require(pre.map.contains_pair(key, value));
            }
        }

        transition!{
            noop() {
            }
        }
    }
