            let s1 = simplify_bool(*e1);
            let s2 = simplify_bool(*e2);
            match (s1, s2) {
                // false && _ = false
                (Expr::Fls, _) => Expr::Fls,
                (_, Expr::Fls) => Expr::Fls,
                // true && e = e
                (Expr::Tru, e) => e,
                (e, Expr::Tru) => e,
                // Otherwise, keep simplified
                (e1, e2) => Expr::And { e1: Box::new(e1), e2: Box::new(e2) },
            }
        }

        Expr::Or { e1, e2 } => {
            let s1 = simplify_bool(*e1);
            let s2 = simplify_bool(*e2);
            match (s1, s2) {
                // true || _ = true
                (Expr::Tru, _) => Expr::Tru,
                (_, Expr::Tru) => Expr::Tru,
                // false || e = e
                (Expr::Fls, e) => e,
                (e, Expr::Fls) => e,
                // Otherwise, keep simplified
                (e1, e2) => Expr::Or { e1: Box::new(e1), e2: Box::new(e2) },
            }
        }

        Expr::Not { e } => {
            let s = simplify_bool(*e);
            match s {
