                Expr::Tru => Expr::Fls,
                // not false = true
                Expr::Fls => Expr::Tru,
                // not (not e) = e
                Expr::Not { e: inner } => *inner,
                // Otherwise, keep simplified
                other => Expr::Not { e: Box::new(other) },
