pub open spec fn gen_option_map<T, U>(
    outputs: Set<Option<T>>,
    f: spec_fn(T) -> U
) -> Set<Option<U>> {
    Set::new(|o: Option<U>| match o {
        Option::None => outputs.contains(Option::None),
        Option::Some(y) => exists|x: T| outputs.contains(Option::Some(x)) && f(x) == y,
